function renderCustomers(){gameWindow.market3d?.sync(customers,selected,levels);$('#customers').innerHTML=customers.map((c,i)=>`<button class="customer ${selected===i?'selected':''}" data-slot="${i}" aria-label="View ${c.name}: ${c.craving.text}"><div class="order"><b>${c.name}</b><span class="craving-short">${c.craving.text}</span><div class="patience"><i style="width:${c.patience*100}%"></i></div></div></button>`).join('');document.querySelectorAll('.customer').forEach(b=>b.onclick=()=>{if(!running||paused||cooking)return;focusCustomer(+b.dataset.slot);hint(`${customers[selected].name}: “${customers[selected].craving.text}”`)})}
