function makeDraft(recipe=[0,1,3]){return{recipe:[...recipe],tech:{brown:0,slices:0,stirs:0},adjust:{butter:0,broth:0,chili:0},tasted:false,feedback:'',customer:customers[selected],tool:{x:.4,y:.4},lastStir:-1}}
