$('#panel-title').textContent=choose?'✦ BUILD YOUR FLAVOR ✦':slice?'✦ YOUR CUT, YOUR TEXTURE ✦':fry?'WATCH THE COLOR':'✦ TASTE & ADJUST ✦';$('#flavor-bars').hidden=slice||fry;$('#flavor-bars').innerHTML=bars(currentProfile());$('#cook-meter').hidden=!fry;$('#brown-marker').style.left=Math.min(98,draft.tech.brown*100)+'%';$('#technique-text').textContent=draft.tech.brown>.82?'Deeply browned — lift off soon!':draft.tech.brown>=.38?(draft.tech.stirs>=3?'Golden and evenly sautéed.':'Golden! Stir a little more for an even sear.'):'Let the pan warm your ingredients.';
