function ready(){return running&&!paused&&cooking&&!cookPaused&&!bookOpen&&draft}
function chooseIngredient(id){if(!ready()||cookStage!=='choose')return;if(draft.recipe.includes(id))draft.recipe=draft.recipe.filter(i=>i!==id);else if(draft.recipe.length<4)draft.recipe.push(id);else{draft.feedback='Three toppings leave room for their flavors to shine.';renderCooking();return}draft.feedback=Flavor.notes[id];draft.tasted=false;renderCooking()}
