function primary(){if(!ready())return;if(cookStage==='choose'){if(draft.recipe.length<2)return;draft.tech={brown:0,slices:0,stirs:0};draft.adjust={butter:0,broth:0,chili:0};draft.feedback='';cookStage='slice'}else if(cookStage==='slice'){if(draft.tech.slices<3)return;draft.feedback='';cookStage='fry'}else if(cookStage==='fry'){if(draft.tech.brown<.12)return;draft.feedback='';draft.tasted=false;cookStage='taste'}else if(!draft.tasted){draft.tasted=true;draft.feedback=Flavor.feedback(currentProfile(),draft.customer.craving,draft.tech)}else{carried={recipe:[...draft.recipe],tech:{...draft.tech},adjust:{...draft.adjust},profile:currentProfile()};draft=null;setCooking(false);renderBowl();hint('Your creation is ready. Walk it to a customer who will enjoy these flavors.');return}renderCooking()}
