function deliver(slot){if(!running||paused||cooking||!carried||gameWindow.walkState?.nearCustomer!==slot)return false;const c=customers[slot];if(!Flavor.matches(carried.profile,c.craving)){const feedback=Flavor.feedback(carried.profile,c.craving,carried.tech);hint(`${c.name}: “${feedback}”`);$('#walk-status').textContent='Try another customer, or return to the counter to adjust your bowl.';return false}gameWindow.market3d?.serve(slot);const key=Flavor.key(carried.recipe),recipe=dishes.find(d=>Flavor.key(d.recipe)===key),title=recipe?.name||'Moonbowl creation',quality=Flavor.quality(carried.tech),isNew=!discoveries[key];discoveries[key]={name:title,recipe:[...carried.recipe],quality,profile:[...carried.profile],night};streak++;const amount=10+carried.recipe.length*2+levels[0]*2+(quality==='Golden sear'?4:0)+(isNew?5:0);bank+=amount;earned+=amount;served++;carried=null;hint(isNew?`New discovery: ${title}! +${amount} ✦`:`${c.name}: “Just what I was craving!” +${amount} ✦`);$('#combo').textContent=isNew?'✦ Recipe discovered!':streak+' happy friends';addCustomer(slot);renderBowl();save();return true}
function interact(){if(!running||paused||cooking)return;const location=gameWindow.walkState;if(location?.nearCustomer!=null){focusCustomer(location.nearCustomer);if(carried)deliver(location.nearCustomer);else{$('#walk-status').textContent=`${customers[selected].name}: ${customers[selected].craving.text}`;hint('Craving selected. Experiment at the counter.')}return}if(location?.atKitchen){openCooking();return}$('#walk-status').textContent='Move closer to the counter or a customer.'}
function showBook(){bookOpen=true;$('#cook-screen').inert=true;$('#discovery-count').textContent=Object.keys(discoveries).length+' of 63 combinations discovered';$('#discovery-list').innerHTML=Object.values(discoveries).length?Object.values(discoveries).map(d=>`<article><b>${d.name}</b><span>${icons(d.recipe)}</span><small>${d.quality} · discovered on night ${d.night}</small></article>`).join(''):'<p>Your first experiment belongs here. Create a bowl a customer loves to discover a recipe.</p>';$('#discovery-screen').hidden=false;stats()}
$('#close-book').onclick=()=>{bookOpen=false;$('#cook-screen').inert=false;$('#discovery-screen').hidden=true;stats()};$('#recipe-book').onclick=showBook;
$('#interact').onclick=interact;$('#leave-kitchen').onclick=()=>setCooking(false);$('#cook-back').onclick=()=>{setCooking(false);hint('Your work is waiting at the counter.')};$('#cook-primary').onclick=primary;$('#cook-assist').onclick=()=>cookStage==='slice'?sliceOnce():stir();$('#cook-secondary').onclick=()=>{if(!ready())return;if(draft.tech.brown<.38){cookStage='fry';draft.feedback=''}else{cookStage='choose';draft.feedback='Try a different balance. Your current bowl will be replaced when you start cooking.'}renderCooking()};$('#cook-pause').onclick=()=>{cookPaused=!cookPaused;renderCooking()};document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>adjust(b.dataset.adjust));
