function end(){running=false;carried=null;bowl=[];draft=null;setCooking(false);gameWindow.market3d?.bowl([]);night++;save();showShop()}
function showShop(){const upgradeNames=['Golden broth','Comfy waiting stools','Moonlit lanterns'],desc=['+2 stars per bowl','Customers wait 12s longer','Nights last 15s longer'];$('#overlay').innerHTML=`<section class="modal"><div class="eyebrow">THE LANTERNS ARE GLOWING LOW</div><h1>A lovely little night.</h1><p>${served} happy customers · ${earned} stars earned<br>${Object.keys(discoveries).length} recipes discovered</p>${upgradeNames.map((n,i)=>{const cost=25*(levels[i]+1);return `<button class="upgrade" data-upgrade="${i}" ${bank<cost||levels[i]>=5?'disabled':''}><span>${n} · Lv ${levels[i]}<br><small>${desc[i]}</small></span><b>${levels[i]>=5?'MAX':cost+' ✦'}</b></button>`}).join('')}<button id="next" class="gold-button">Open night ${night} ↗</button><small>Discoveries and upgrades save automatically.</small></section>`;$('#overlay').classList.remove('hidden');$('#next').onclick=start;document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{const i=+b.dataset.upgrade,cost=25*(levels[i]+1);if(bank>=cost&&levels[i]<5){bank-=cost;levels[i]++;save();stats();showShop()}})}
$('#start').onclick=start;$('#pause').onclick=()=>{if(!running)return;paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Resume game':'Pause game');gameWindow.market3d?.stopMoving?.();stats();hint(paused?'The market is paused.':'Welcome back to your market.')};document.addEventListener('visibilitychange',()=>{if(document.hidden&&running){if(cooking){cookPaused=true;stats()}else if(!paused)$('#pause').click()}});
let renderElapsed=0;function frame(t){const dt=Math.max(0,Math.min((t-last)/1000,.1));last=t;if(running&&!paused){if(cooking){if(draft&&cookStage==='fry'&&!cookPaused&&!bookOpen){draft.tech.brown=Math.min(1,draft.tech.brown+dt*(draft.tech.slices>=6?.045:.035));renderElapsed+=dt;if(renderElapsed>.1){renderElapsed=0;renderCooking()}}}else{remaining-=dt;customers.forEach((c,i)=>{c.patience-=dt/c.max;if(c.patience<=0){hint(`${c.name} headed home. Another friend is here!`);addCustomer(i)}});document.querySelectorAll('.patience i').forEach((el,i)=>{el.style.width=customers[i].patience*100+'%';el.style.background=customers[i].patience<.25?'#c47a76':'#76a68a'});if(remaining<=0)end()}stats()}requestAnimationFrame(frame)}
gameWindow.marketGame={interact,deliver,focusCustomer,openCooking,chooseIngredient,sliceOnce,stir,primary,adjust,showBook};stats();for(let i=0;i<3;i++)addCustomer(i);requestAnimationFrame(frame);
